fn is_odd_at_odd_index(arr: &Vec<usize>) -> bool {
    for (i, &val) in arr.iter().enumerate() {
        // Check that the parity of the index matches the parity of the value.
        if (i % 2) != (val % 2) {
            return false;
        }
    }
    true
}

